{
  "a_requests": [
    {
      "a_request": "R1",
      "b_asked": "서울시 조례상 금연구역에서 불붙은 담배를 들고만 있는 행위가 흡연 금지 규정과 과태료 적용 대상인지 여부",
      "c_basis": "DIRECT",
      "d_claims": [
        {
          "a_text": "적용됩니다. 이 조례에서 \"흡연\"은 담배를 피우는 행위뿐 아니라 불이 붙은 담배를 소지하는 것도 포함하므로, 불붙은 담배를 들고만 있는 행위도 흡연에 해당합니다. 따라서 제5조제4항에 따라 지정된 금연구역에서는 그러한 행위를 해서는 안 되며, 이를 위반하면 제10조제1항에 따라 10만원의 과태료가 부과됩니다.",
          "b_ids": "금연:제2조제2호, 금연:제5조제4항, 금연:제10조제1항"
        }
      ],
      "e_status": "ANSWERED"
    }
  ]
}
